// Lookup GCP length from the CSV table published by GS1 (simplified).
class GcpLengthTable {
  final Map<int, int> _prefixToLen;
  GcpLengthTable(this._prefixToLen);

  /// Returns the GCP length for a given GTIN (14-digit padded form).
  int lengthFor(String gtin14) {
    // Ignore the leading indicator digit for GTIN-14 → work on the following 12 digits.
    final numeric = int.parse(gtin14.substring(1, 13));
    // Table has entries by 4-digit prefix; look up progressively.
    for (int prefixLen = 12; prefixLen >= 3; prefixLen--) {
      final key = int.parse(gtin14.substring(1, 1 + prefixLen));
      final len = _prefixToLen[key];
      if (len != null) return len;
    }
    return 7; // conservative default (not authoritative)
  }

  String extractGcp(String gtin14) {
    final len = lengthFor(gtin14);
    return gtin14.substring(1, 1 + len);
  }
}

// Usage:
final table = GcpLengthTable(loadGcpTable());
final gcp = table.extractGcp('08901234567890');   // e.g. '8901234'
